BEGIN;
CREATE TABLE public.forge_vtt_messages(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,campaign_id uuid NOT NULL REFERENCES public.forge_vtt_campaigns(id) ON DELETE CASCADE,actor_id uuid REFERENCES auth.users(id) ON DELETE SET NULL,request_id uuid NOT NULL DEFAULT gen_random_uuid(),created_at timestamptz NOT NULL DEFAULT clock_timestamp(),scope text NOT NULL CHECK(scope IN ('public','whisper','gm','controllers')),recipient_id uuid REFERENCES auth.users(id) ON DELETE SET NULL,token_id uuid REFERENCES public.forge_vtt_entities(id) ON DELETE SET NULL,speaker text NOT NULL,avatar text,color text NOT NULL DEFAULT '#b4a7ff',kind text NOT NULL CHECK(kind IN ('text','emote','roll','card','image','combat')),body text NOT NULL DEFAULT '' CHECK(length(body)<=10000),payload jsonb NOT NULL DEFAULT '{}' CHECK(octet_length(payload::text)<=65536),verified boolean NOT NULL DEFAULT false,UNIQUE(campaign_id,actor_id,request_id));
CREATE INDEX vtt_messages_history ON public.forge_vtt_messages(campaign_id,id DESC);
ALTER TABLE public.forge_vtt_messages ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.forge_vtt_messages FROM anon,authenticated;GRANT SELECT ON public.forge_vtt_messages TO authenticated;
CREATE POLICY vtt_message_read ON public.forge_vtt_messages TO authenticated USING(forge_vtt_private.member_of(campaign_id) AND (scope='public' OR actor_id=(select auth.uid()) OR forge_vtt_private.dm_of(campaign_id) AND scope IN ('gm','controllers') OR scope='whisper' AND recipient_id=(select auth.uid()) OR scope='controllers' AND token_id IS NOT NULL AND forge_vtt_private.controls_token(campaign_id,token_id)) AND (token_id IS NULL OR forge_vtt_private.entity_readable(campaign_id,token_id)));
CREATE TABLE public.forge_vtt_combat(campaign_id uuid PRIMARY KEY REFERENCES public.forge_vtt_campaigns(id) ON DELETE CASCADE,revision bigint NOT NULL DEFAULT 0,data jsonb NOT NULL DEFAULT '{"entries":[],"round":1,"activeTokenId":null,"timerSeconds":0}' CHECK(octet_length(data::text)<=262144));
ALTER TABLE public.forge_vtt_combat ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.forge_vtt_combat FROM anon,authenticated;GRANT SELECT ON public.forge_vtt_combat TO authenticated;
CREATE POLICY vtt_combat_dm ON public.forge_vtt_combat TO authenticated USING(forge_vtt_private.dm_of(campaign_id));
CREATE TABLE public.forge_vtt_macros(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),campaign_id uuid NOT NULL REFERENCES public.forge_vtt_campaigns(id) ON DELETE CASCADE,owner_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,name text NOT NULL CHECK(length(name) BETWEEN 1 AND 80),formula text NOT NULL CHECK(length(formula) BETWEEN 1 AND 2000),template text NOT NULL DEFAULT '' CHECK(length(template)<=2000),token_id uuid REFERENCES public.forge_vtt_entities(id) ON DELETE CASCADE,slot integer CHECK(slot BETWEEN 1 AND 9));
CREATE INDEX vtt_macros_owner ON public.forge_vtt_macros(campaign_id,owner_id);
ALTER TABLE public.forge_vtt_macros ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.forge_vtt_macros FROM anon,authenticated;GRANT SELECT ON public.forge_vtt_macros TO authenticated;
CREATE POLICY vtt_macro_self ON public.forge_vtt_macros TO authenticated USING(owner_id=(select auth.uid()) AND forge_vtt_private.member_of(campaign_id));
CREATE TABLE public.forge_vtt_play_events(campaign_id uuid PRIMARY KEY REFERENCES public.forge_vtt_campaigns(id) ON DELETE CASCADE,sequence bigint NOT NULL DEFAULT 1);
ALTER TABLE public.forge_vtt_play_events ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.forge_vtt_play_events FROM anon,authenticated;GRANT SELECT ON public.forge_vtt_play_events TO authenticated;
CREATE POLICY vtt_play_counter ON public.forge_vtt_play_events TO authenticated USING(forge_vtt_private.member_of(campaign_id));
CREATE TABLE forge_vtt_private.play_rate(campaign_id uuid REFERENCES public.forge_vtt_campaigns(id) ON DELETE CASCADE,user_id uuid REFERENCES auth.users(id) ON DELETE CASCADE,minute bigint,hits integer NOT NULL DEFAULT 1,PRIMARY KEY(campaign_id,user_id));
ALTER TABLE forge_vtt_private.play_rate ENABLE ROW LEVEL SECURITY;REVOKE ALL ON forge_vtt_private.play_rate FROM PUBLIC,anon,authenticated;
CREATE TABLE forge_vtt_private.play_actions(campaign_id uuid REFERENCES public.forge_vtt_campaigns(id) ON DELETE CASCADE,actor_id uuid REFERENCES auth.users(id) ON DELETE CASCADE,request_id uuid,PRIMARY KEY(campaign_id,actor_id,request_id));
ALTER TABLE forge_vtt_private.play_actions ENABLE ROW LEVEL SECURITY;REVOKE ALL ON forge_vtt_private.play_actions FROM PUBLIC,anon,authenticated;
CREATE FUNCTION forge_vtt_private.play_notify(c uuid) RETURNS void LANGUAGE sql SECURITY DEFINER SET search_path='' AS $$INSERT INTO public.forge_vtt_play_events(campaign_id) VALUES(c) ON CONFLICT(campaign_id) DO UPDATE SET sequence=forge_vtt_play_events.sequence+1$$;
CREATE FUNCTION forge_vtt_private.play_limit(c uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$DECLARE hits integer;BEGIN IF NOT forge_vtt_private.regular_user(auth.uid()) OR NOT forge_vtt_private.member_of(c) THEN RAISE EXCEPTION 'Campaign unavailable' USING ERRCODE='42501';END IF;INSERT INTO forge_vtt_private.play_rate AS r(campaign_id,user_id,minute) VALUES(c,auth.uid(),floor(extract(epoch from clock_timestamp())/60)) ON CONFLICT(campaign_id,user_id) DO UPDATE SET hits=CASE WHEN r.minute=EXCLUDED.minute THEN r.hits+1 ELSE 1 END,minute=EXCLUDED.minute RETURNING r.hits INTO hits;IF hits>90 THEN RAISE EXCEPTION 'Play action limit reached; try again in a minute';END IF;END$$;
CREATE FUNCTION forge_vtt_private.play_post(c uuid,p jsonb,result jsonb DEFAULT NULL) RETURNS bigint LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$DECLARE tid uuid:=(p->>'tokenId')::uuid;recipient uuid:=(p->>'recipientId')::uuid;audience text:=coalesce(p->>'scope','public');speaker text;avatar text:=p->>'avatar';kind text:=coalesce(p->>'kind','text');body text:=coalesce(p->>'body','');mid bigint;entity public.forge_vtt_entities;BEGIN
 IF NOT forge_vtt_private.member_of(c) OR audience NOT IN ('public','whisper','gm') OR kind NOT IN ('text','emote','roll','card','image') OR length(body)>10000 OR octet_length(p::text)>32768 THEN RAISE EXCEPTION 'Invalid message';END IF;
 IF kind='roll' AND result IS NULL THEN RAISE EXCEPTION 'Rolls must use the trusted gateway' USING ERRCODE='42501';END IF;
 IF recipient IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.forge_vtt_campaign_members WHERE campaign_id=c AND user_id=recipient) OR audience='whisper' AND recipient IS NULL THEN RAISE EXCEPTION 'Whisper recipient unavailable';END IF;
 SELECT display_name INTO speaker FROM public.forge_vtt_campaign_members WHERE campaign_id=c AND user_id=auth.uid();
 IF tid IS NOT NULL THEN SELECT * INTO entity FROM public.forge_vtt_entities WHERE id=tid AND campaign_id=c AND forge_vtt_entities.kind='token' AND deleted_at IS NULL;IF NOT FOUND OR NOT (forge_vtt_private.dm_of(c) OR forge_vtt_private.controls_token(c,tid)) THEN RAISE EXCEPTION 'Speaker permission denied' USING ERRCODE='42501';END IF;SELECT name INTO speaker FROM public.forge_vtt_tokens WHERE id=tid;IF entity.visibility='dm' OR entity.layer='gm' THEN audience:='gm';recipient:=NULL;END IF;END IF;
 IF avatar IS NOT NULL AND (length(avatar)>2000 OR avatar!~'^https://') THEN avatar:=NULL;END IF;
 IF kind='image' AND (body!~'^https://' OR length(body)>2000) THEN RAISE EXCEPTION 'Images need an HTTPS URL';END IF;
 IF kind='card' AND (NOT forge_vtt_private.allow_keys(p->'card',ARRAY['type','title','text','url']) OR length(p#>>'{card,title}')>120 OR length(p#>>'{card,text}')>8000 OR coalesce(p#>>'{card,type}','') NOT IN ('spell','item','note') OR p#>>'{card,url}' IS NOT NULL AND p#>>'{card,url}'!~'^https://') THEN RAISE EXCEPTION 'Invalid card';END IF;
 INSERT INTO public.forge_vtt_messages(campaign_id,actor_id,request_id,scope,recipient_id,token_id,speaker,avatar,color,kind,body,payload,verified) VALUES(c,auth.uid(),coalesce((p->>'requestId')::uuid,gen_random_uuid()),audience,recipient,tid,coalesce(speaker,'Adventurer'),avatar,(ARRAY['#c5a3ff','#79c9ff','#80d8aa','#ffbb75','#ff92b1','#e7d87a'])[(get_byte(decode(md5(auth.uid()::text),'hex'),0)%6)+1],kind,body,CASE WHEN kind='roll' THEN jsonb_build_object('rolls',result) WHEN kind='card' THEN p->'card' ELSE '{}' END,result IS NOT NULL) ON CONFLICT(campaign_id,actor_id,request_id) DO UPDATE SET request_id=EXCLUDED.request_id RETURNING id INTO mid;
 PERFORM forge_vtt_private.play_notify(c);RETURN mid;END$$;
CREATE FUNCTION forge_vtt_private.play_context(c uuid,tid uuid) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path='' AS $$DECLARE data jsonb;refs jsonb:='{}';k text;v jsonb;BEGIN
 IF NOT forge_vtt_private.member_of(c) THEN RAISE EXCEPTION 'Campaign unavailable' USING ERRCODE='42501';END IF;
 IF tid IS NULL THEN RETURN jsonb_build_object('refs','{}'::jsonb,'initiative',0,'dex',0,'alert',false);END IF;
 IF NOT (forge_vtt_private.dm_of(c) OR forge_vtt_private.controls_token(c,tid)) THEN RAISE EXCEPTION 'Use a token you control for stat references' USING ERRCODE='42501';END IF;
 SELECT p.data INTO data FROM public.forge_vtt_private_data p WHERE p.campaign_id=c AND p.entity_id=tid AND p.scope='controller';
 FOR k,v IN SELECT * FROM jsonb_each(coalesce(data#>'{details,stats}','{}')) LOOP IF jsonb_typeof(v)='number' AND abs((v::text)::numeric)<=100000 THEN refs:=refs||jsonb_build_object(upper(k),v);END IF;END LOOP;
 FOREACH k IN ARRAY ARRAY['STR','DEX','CON','INT','WIS','CHA','PROF'] LOOP IF NOT refs?k THEN refs:=refs||jsonb_build_object(k,0);END IF;END LOOP;
 refs:=refs||jsonb_build_object('@TOKEN.HP',coalesce(data->'hp','0'),'@TOKEN.MAXHP',coalesce(data->'maxHp','0'),'@TOKEN.AC',coalesce(data#>'{details,ac}','0'),'@TOKEN.SPEED',coalesce(data#>'{details,speed}','0'));
 RETURN jsonb_build_object('refs',refs,'initiative',coalesce(data#>'{details,initiative}','0'),'dex',coalesce(refs->'DEX','0'),'alert',coalesce(data#>'{details,stats,Alert}','false'));END$$;
CREATE FUNCTION forge_vtt_private.play_get(c uuid,before_id bigint DEFAULT NULL) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path='' AS $$DECLARE combat jsonb;revision bigint;entry jsonb;entries jsonb:='[]';tid uuid;tok public.forge_vtt_tokens;private jsonb;own boolean;hp numeric;maximum numeric;BEGIN
 IF NOT forge_vtt_private.regular_user(auth.uid()) OR NOT forge_vtt_private.member_of(c) THEN RAISE EXCEPTION 'Campaign unavailable' USING ERRCODE='42501';END IF;
 SELECT data,forge_vtt_combat.revision INTO combat,revision FROM public.forge_vtt_combat WHERE campaign_id=c;combat:=coalesce(combat,'{"entries":[],"round":1,"activeTokenId":null,"timerSeconds":0}');
 FOR entry IN SELECT value FROM jsonb_array_elements(combat->'entries') LOOP tid:=(entry->>'tokenId')::uuid;IF NOT forge_vtt_private.entity_readable(c,tid) THEN CONTINUE;END IF;SELECT * INTO tok FROM public.forge_vtt_tokens WHERE id=tid;SELECT data INTO private FROM public.forge_vtt_private_data WHERE entity_id=tid AND scope='controller';own:=forge_vtt_private.dm_of(c) OR forge_vtt_private.controls_token(c,tid);hp:=coalesce((private->>'hp')::numeric,0);maximum:=greatest(1,coalesce((private->>'maxHp')::numeric,1));
 entry:=entry||jsonb_build_object('name',tok.name,'color',tok.border_color,'owned',own,'conditions',(SELECT coalesce(public_data->'conditions','[]') FROM public.forge_vtt_entities WHERE id=tid));
 IF own OR entry->>'hpDisplay'='numbers' OR coalesce((private#>>'{details,hpVisible}')::boolean,false) THEN entry:=entry||jsonb_build_object('hp',hp,'maxHp',maximum,'tempHp',coalesce(private#>'{details,tempHp}','0'));
 ELSIF entry->>'hpDisplay'='status' THEN entry:=entry||jsonb_build_object('health',CASE WHEN hp=0 THEN 'Defeated' WHEN hp/maximum<=.25 THEN 'Near death' WHEN hp/maximum<=.5 THEN 'Bloodied' ELSE 'Healthy' END);END IF;
 IF own OR coalesce((entry->>'showAc')::boolean,false) THEN entry:=entry||jsonb_build_object('ac',private#>'{details,ac}');END IF;
 entries:=entries||jsonb_build_array(entry);END LOOP;
 combat:=(combat-'history')||jsonb_build_object('entries',entries,'revision',coalesce(revision,0));tid:=(combat->>'activeTokenId')::uuid;IF tid IS NOT NULL AND NOT forge_vtt_private.entity_readable(c,tid) THEN combat:=combat||jsonb_build_object('activeTokenId',NULL);END IF;
 RETURN jsonb_build_object('combat',combat,'messages',coalesce((SELECT jsonb_agg(row ORDER BY (row->>'id')::bigint) FROM (SELECT to_jsonb(m) row FROM public.forge_vtt_messages m WHERE m.campaign_id=c AND (before_id IS NULL OR m.id<before_id) AND (m.scope='public' OR m.actor_id=auth.uid() OR m.scope IN ('gm','controllers') AND forge_vtt_private.dm_of(c) OR m.scope='whisper' AND m.recipient_id=auth.uid() OR m.scope='controllers' AND m.token_id IS NOT NULL AND forge_vtt_private.controls_token(c,m.token_id)) AND (m.token_id IS NULL OR forge_vtt_private.entity_readable(c,m.token_id)) ORDER BY m.id DESC LIMIT 100) sub),'[]'),'macros',coalesce((SELECT jsonb_agg(to_jsonb(m)) FROM public.forge_vtt_macros m WHERE m.campaign_id=c AND m.owner_id=auth.uid()),'[]'));
 END$$;
CREATE FUNCTION forge_vtt_private.combat_action(c uuid,p jsonb,rolled jsonb DEFAULT NULL) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$DECLARE d jsonb;entries jsonb;entry jsonb;old jsonb;target uuid;active uuid;action text:=p->>'action';actual bigint;position integer;size integer;index integer;round integer;item jsonb;duration jsonb;durations jsonb;name text;context jsonb;result jsonb;history jsonb;conditions jsonb;BEGIN
 INSERT INTO public.forge_vtt_combat(campaign_id) VALUES(c) ON CONFLICT DO NOTHING;SELECT data,forge_vtt_combat.revision INTO d,actual FROM public.forge_vtt_combat WHERE campaign_id=c FOR UPDATE;
 IF actual IS DISTINCT FROM (p->>'expected')::bigint THEN RAISE EXCEPTION 'Combat changed; update before editing' USING ERRCODE='40001';END IF;
 active:=(d->>'activeTokenId')::uuid;target:=(p->>'tokenId')::uuid;
 IF NOT forge_vtt_private.dm_of(c) AND (action NOT IN ('ready','delay') OR target IS DISTINCT FROM active OR NOT forge_vtt_private.controls_token(c,target)) THEN RAISE EXCEPTION 'DM combat controls required' USING ERRCODE='42501';END IF;
 entries:=d->'entries';history:=coalesce(d->'history','[]');old:=d-'history';round:=coalesce((d->>'round')::integer,1);
 IF action='add' THEN
 IF jsonb_typeof(p->'entries')<>'array' OR jsonb_array_length(p->'entries')>100 THEN RAISE EXCEPTION 'Add at most 100 combatants';END IF;
 FOR item IN SELECT value FROM jsonb_array_elements(p->'entries') LOOP target:=(item->>'tokenId')::uuid;IF NOT forge_vtt_private.entity_readable(c,target) OR NOT EXISTS(SELECT 1 FROM public.forge_vtt_tokens WHERE id=target) THEN RAISE EXCEPTION 'Combatant unavailable';END IF;
 context:=forge_vtt_private.play_context(c,target);result:=rolled->target::text;
 IF NOT forge_vtt_private.number_ok(item,'initiative',-1000,1000) THEN RAISE EXCEPTION 'Invalid initiative';END IF;
 entry:=jsonb_build_object('tokenId',target,'initiative',coalesce((result->>'total')::numeric,(item->>'initiative')::numeric,0),'dex',coalesce(context->'dex','0'),'hpDisplay','status','showAc',false,'durations','[]'::jsonb,'ready',false,'delayed',false);
 entries:=coalesce((SELECT jsonb_agg(e) FROM jsonb_array_elements(entries) e WHERE e->>'tokenId'<>target::text),'[]')||jsonb_build_array(entry);END LOOP;
 IF jsonb_array_length(entries)>100 THEN RAISE EXCEPTION 'Combatant limit is 100';END IF;
 SELECT coalesce(jsonb_agg(e ORDER BY (e->>'initiative')::numeric DESC,(e->>'dex')::numeric DESC,ord),'[]') INTO entries FROM jsonb_array_elements(entries) WITH ORDINALITY AS t(e,ord);
 ELSIF action='remove' THEN entries:=coalesce((SELECT jsonb_agg(e) FROM jsonb_array_elements(entries) e WHERE e->>'tokenId'<>target::text),'[]');IF active=target THEN active:=(entries->0->>'tokenId')::uuid;END IF;
 ELSIF action='settings' THEN IF NOT forge_vtt_private.number_ok(p,'timerSeconds',0,3600) THEN RAISE EXCEPTION 'Invalid timer';END IF;d:=d||jsonb_build_object('timerSeconds',coalesce((p->>'timerSeconds')::integer,0));
 ELSIF action='entry' THEN
 IF coalesce(p->>'hpDisplay','status') NOT IN ('hidden','status','numbers') OR NOT forge_vtt_private.number_ok(p,'initiative',-1000,1000) THEN RAISE EXCEPTION 'Invalid combat display';END IF;
 entries:=coalesce((SELECT jsonb_agg(CASE WHEN e->>'tokenId'=target::text THEN e||jsonb_build_object('initiative',coalesce(p->'initiative',e->'initiative'),'hpDisplay',coalesce(p->>'hpDisplay','status'),'showAc',coalesce((p->>'showAc')::boolean,false)) ELSE e END) FROM jsonb_array_elements(entries) e),'[]');
 ELSIF action='order' THEN IF jsonb_typeof(p->'ids')<>'array' OR jsonb_array_length(p->'ids')<>jsonb_array_length(entries) OR (SELECT count(DISTINCT value) FROM jsonb_array_elements(p->'ids'))<>jsonb_array_length(entries) OR EXISTS(SELECT 1 FROM jsonb_array_elements_text(p->'ids') v WHERE NOT EXISTS(SELECT 1 FROM jsonb_array_elements(entries) e WHERE e->>'tokenId'=v)) THEN RAISE EXCEPTION 'Order must include each combatant once';END IF;
 SELECT jsonb_agg(e ORDER BY ord) INTO entries FROM jsonb_array_elements_text(p->'ids') WITH ORDINALITY AS t(v,ord) JOIN LATERAL jsonb_array_elements(entries) e ON e->>'tokenId'=v;
 ELSIF action='duration' THEN
 name:=btrim(p->>'name');IF NOT p ?& ARRAY['name','rounds'] OR length(name) NOT BETWEEN 1 AND 60 OR NOT forge_vtt_private.number_ok(p,'rounds',1,1000) THEN RAISE EXCEPTION 'Invalid condition duration';END IF;
 entries:=coalesce((SELECT jsonb_agg(CASE WHEN e->>'tokenId'=target::text THEN e||jsonb_build_object('durations',coalesce((SELECT jsonb_agg(x) FROM jsonb_array_elements(e->'durations') x WHERE x->>'name'<>name),'[]')||jsonb_build_array(jsonb_build_object('name',name,'remaining',(p->>'rounds')::integer))) ELSE e END) FROM jsonb_array_elements(entries) e),'[]');
 UPDATE public.forge_vtt_entities SET public_data=jsonb_set(public_data,'{conditions}',coalesce(public_data->'conditions','[]')||CASE WHEN coalesce(public_data->'conditions','[]')?name THEN '[]'::jsonb ELSE jsonb_build_array(name) END),revision=revision+1 WHERE id=target AND campaign_id=c;
 ELSIF action IN ('start','next','previous','delay','ready','end') THEN
 size:=jsonb_array_length(entries);IF action='end' THEN active:=NULL;
 ELSIF action='previous' THEN IF jsonb_array_length(history)>0 THEN d:=history->(jsonb_array_length(history)-1);history:=history-(jsonb_array_length(history)-1);entries:=d->'entries';active:=(d->>'activeTokenId')::uuid;round:=(d->>'round')::integer;FOR entry IN SELECT value FROM jsonb_array_elements(entries) LOOP FOR duration IN SELECT value FROM jsonb_array_elements(entry->'durations') LOOP UPDATE public.forge_vtt_entities SET public_data=jsonb_set(public_data,'{conditions}',coalesce(public_data->'conditions','[]')||CASE WHEN coalesce(public_data->'conditions','[]')?(duration->>'name') THEN '[]'::jsonb ELSE jsonb_build_array(duration->>'name') END),revision=revision+1 WHERE id=(entry->>'tokenId')::uuid AND campaign_id=c;END LOOP;END LOOP;END IF;
 ELSIF action='ready' THEN entries:=coalesce((SELECT jsonb_agg(CASE WHEN e->>'tokenId'=target::text THEN e||'{"ready":true}' ELSE e END) FROM jsonb_array_elements(entries) e),'[]');
 ELSIF size>0 THEN
 SELECT ord::integer-1 INTO position FROM jsonb_array_elements(entries) WITH ORDINALITY AS t(e,ord) WHERE e->>'tokenId'=active::text;position:=coalesce(position,-1);
 IF action='start' THEN round:=1;index:=0;
 ELSIF action='delay' THEN entry:=entries->position;entries:=(entries-position)||jsonb_build_array(entry||'{"delayed":true}');index:=CASE WHEN position>=size-1 THEN 0 ELSE position END;IF position>=size-1 THEN round:=round+1;END IF;
 ELSE index:=(position+1)%size;IF index=0 AND position>=0 THEN round:=round+1;END IF;END IF;
 IF round>coalesce((old->>'round')::integer,1) THEN
 result:='[]';FOR entry IN SELECT value FROM jsonb_array_elements(entries) LOOP durations:='[]';FOR duration IN SELECT value FROM jsonb_array_elements(entry->'durations') LOOP IF (duration->>'remaining')::integer>1 THEN durations:=durations||jsonb_build_array(duration||jsonb_build_object('remaining',(duration->>'remaining')::integer-1));ELSE UPDATE public.forge_vtt_entities SET public_data=jsonb_set(public_data,'{conditions}',coalesce((SELECT jsonb_agg(v) FROM jsonb_array_elements(coalesce(public_data->'conditions','[]')) v WHERE v#>>'{}'<>duration->>'name'),'[]')),revision=revision+1 WHERE id=(entry->>'tokenId')::uuid AND campaign_id=c;END IF;END LOOP;result:=result||jsonb_build_array(entry||jsonb_build_object('durations',durations));END LOOP;entries:=result;END IF;
 active:=(entries->index->>'tokenId')::uuid;
 END IF;
 ELSE RAISE EXCEPTION 'Unknown combat action';END IF;
 IF action<>'previous' THEN history:=history||jsonb_build_array(old);IF jsonb_array_length(history)>30 THEN history:=history-0;END IF;END IF;
 d:=d||jsonb_build_object('entries',entries,'activeTokenId',active,'round',round,'startedAt',floor(extract(epoch from clock_timestamp())*1000),'history',history);
 UPDATE public.forge_vtt_combat SET data=d,revision=actual+1 WHERE campaign_id=c;
 IF action IN ('next','start','previous','delay','duration') THEN UPDATE public.forge_vtt_campaigns SET revision=revision+1,updated_at=now() WHERE id=c;END IF;
 IF active IS NOT NULL AND action IN ('start','next','previous','delay') THEN INSERT INTO public.forge_vtt_messages(campaign_id,actor_id,token_id,scope,speaker,kind,body,payload) VALUES(c,auth.uid(),active,'public','Combat','combat','Round '||round::text||' · '||(SELECT forge_vtt_tokens.name FROM public.forge_vtt_tokens WHERE id=active)||'’s turn',jsonb_build_object('turn',true));END IF;
 PERFORM forge_vtt_private.play_notify(c);END$$;
CREATE FUNCTION public.forge_vtt_play(p_action text,p_payload jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$DECLARE c uuid:=(p_payload->>'campaignId')::uuid;tid uuid;macro public.forge_vtt_macros;BEGIN
 IF NOT forge_vtt_private.regular_user(auth.uid()) OR NOT forge_vtt_private.member_of(c) OR octet_length(p_payload::text)>65536 THEN RAISE EXCEPTION 'Campaign unavailable' USING ERRCODE='42501';END IF;
 IF p_action='get' THEN RETURN forge_vtt_private.play_get(c,(p_payload->>'before')::bigint);
 ELSIF p_action='context' THEN RETURN forge_vtt_private.play_context(c,(p_payload->>'tokenId')::uuid);END IF;
 PERFORM forge_vtt_private.play_limit(c);
 IF forge_vtt_private.user_role(c,auth.uid())='spectator' THEN RAISE EXCEPTION 'Spectators have read-only play access' USING ERRCODE='42501';END IF;
 IF p_action='send' THEN PERFORM forge_vtt_private.play_post(c,p_payload);
 ELSIF p_action='combat' THEN
 IF (p_payload->>'requestId') IS NULL THEN RAISE EXCEPTION 'Request ID required';END IF;PERFORM 1 FROM public.forge_vtt_campaigns WHERE id=c FOR UPDATE;IF EXISTS(SELECT 1 FROM forge_vtt_private.play_actions WHERE campaign_id=c AND actor_id=auth.uid() AND request_id=(p_payload->>'requestId')::uuid) THEN RETURN forge_vtt_private.play_get(c);END IF;
 PERFORM forge_vtt_private.combat_action(c,p_payload);INSERT INTO forge_vtt_private.play_actions VALUES(c,auth.uid(),(p_payload->>'requestId')::uuid);
 ELSIF p_action='macro_save' THEN
 tid:=(p_payload->>'tokenId')::uuid;IF tid IS NOT NULL AND NOT (forge_vtt_private.dm_of(c) OR forge_vtt_private.controls_token(c,tid)) THEN RAISE EXCEPTION 'Token macro permission denied' USING ERRCODE='42501';END IF;
 IF (SELECT count(*) FROM public.forge_vtt_macros WHERE owner_id=auth.uid() AND campaign_id=c)>=100 AND NOT EXISTS(SELECT 1 FROM public.forge_vtt_macros WHERE id=(p_payload->>'id')::uuid AND owner_id=auth.uid() AND campaign_id=c) THEN RAISE EXCEPTION 'Macro limit is 100 per campaign';END IF;
 INSERT INTO public.forge_vtt_macros(id,campaign_id,owner_id,name,formula,template,token_id,slot) VALUES((p_payload->>'id')::uuid,c,auth.uid(),p_payload->>'name',p_payload->>'formula',coalesce(p_payload->>'template',''),tid,(p_payload->>'slot')::integer) ON CONFLICT(id) DO UPDATE SET name=EXCLUDED.name,formula=EXCLUDED.formula,template=EXCLUDED.template,token_id=EXCLUDED.token_id,slot=EXCLUDED.slot WHERE forge_vtt_macros.owner_id=auth.uid() AND forge_vtt_macros.campaign_id=c;
 ELSIF p_action='macro_delete' THEN DELETE FROM public.forge_vtt_macros WHERE id=(p_payload->>'id')::uuid AND campaign_id=c AND owner_id=auth.uid();
 ELSE RAISE EXCEPTION 'Unknown play action';END IF;RETURN forge_vtt_private.play_get(c);END$$;
CREATE FUNCTION public.forge_vtt_roll_gateway(p_actor uuid,p_payload jsonb,p_rolls jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$DECLARE c uuid:=(p_payload->>'campaignId')::uuid;tid uuid;item jsonb;uid_before text;BEGIN
 IF NOT forge_vtt_private.regular_user(p_actor) OR forge_vtt_private.user_role(c,p_actor) NOT IN ('dm','player') OR forge_vtt_private.user_role(c,p_actor) IS NULL OR octet_length(p_rolls::text)>65536 THEN RAISE EXCEPTION 'Roll permission denied' USING ERRCODE='42501';END IF;
 PERFORM set_config('request.jwt.claim.sub',p_actor::text,true);PERFORM forge_vtt_private.play_limit(c);
 IF p_payload->>'action'='initiative' THEN IF NOT forge_vtt_private.dm_of(c) THEN RAISE EXCEPTION 'DM initiative required' USING ERRCODE='42501';END IF;PERFORM 1 FROM public.forge_vtt_campaigns WHERE id=c FOR UPDATE;
 IF NOT EXISTS(SELECT 1 FROM forge_vtt_private.play_actions WHERE campaign_id=c AND actor_id=p_actor AND request_id=(p_payload->>'requestId')::uuid) THEN PERFORM forge_vtt_private.combat_action(c,p_payload||jsonb_build_object('action','add'),p_rolls);FOR item IN SELECT value FROM jsonb_array_elements(p_payload->'entries') LOOP tid:=(item->>'tokenId')::uuid;PERFORM forge_vtt_private.play_post(c,jsonb_build_object('kind','roll','scope','gm','tokenId',tid,'body','Initiative','requestId',gen_random_uuid()),jsonb_build_array(jsonb_build_object('label','Initiative')||(p_rolls->tid::text)));END LOOP;INSERT INTO forge_vtt_private.play_actions VALUES(c,p_actor,(p_payload->>'requestId')::uuid);END IF;
 ELSE PERFORM forge_vtt_private.play_context(c,(p_payload->>'tokenId')::uuid);PERFORM forge_vtt_private.play_post(c,p_payload||'{"kind":"roll"}',p_rolls);END IF;
 RETURN forge_vtt_private.play_get(c);END$$;
REVOKE ALL ON FUNCTION public.forge_vtt_play(text,jsonb) FROM PUBLIC,anon;GRANT EXECUTE ON FUNCTION public.forge_vtt_play(text,jsonb) TO authenticated;
REVOKE ALL ON FUNCTION public.forge_vtt_roll_gateway(uuid,jsonb,jsonb) FROM PUBLIC,anon,authenticated;GRANT EXECUTE ON FUNCTION public.forge_vtt_roll_gateway(uuid,jsonb,jsonb) TO service_role;
REVOKE ALL ON FUNCTION forge_vtt_private.play_notify(uuid),forge_vtt_private.play_limit(uuid),forge_vtt_private.play_post(uuid,jsonb,jsonb),forge_vtt_private.play_context(uuid,uuid),forge_vtt_private.play_get(uuid,bigint),forge_vtt_private.combat_action(uuid,jsonb,jsonb) FROM PUBLIC,anon,authenticated;
DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM pg_publication_tables WHERE pubname='supabase_realtime' AND schemaname='public' AND tablename='forge_vtt_play_events') THEN ALTER PUBLICATION supabase_realtime ADD TABLE public.forge_vtt_play_events;END IF;END$$;

-- Model edits and damage widgets share one log path; no client-supplied combat totals are trusted.
ALTER FUNCTION forge_vtt_private.apply_changes(uuid,uuid,jsonb) RENAME TO p4_apply_changes;
CREATE FUNCTION forge_vtt_private.apply_changes(c uuid,op uuid,changes jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$DECLARE before_tokens jsonb;item jsonb;after_data jsonb;meta jsonb;damage numeric;healing numeric;result jsonb;BEGIN
 IF EXISTS(SELECT 1 FROM public.forge_vtt_commands WHERE campaign_id=c AND operation_id=op) THEN RETURN forge_vtt_private.p4_apply_changes(c,op,changes);END IF;
 SELECT coalesce(jsonb_agg(jsonb_build_object('id',t.id,'name',t.name,'hp',p.data->'hp','tempHp',p.data#>'{details,tempHp}','conditions',e.public_data->'conditions')),'[]') INTO before_tokens FROM public.forge_vtt_tokens t JOIN public.forge_vtt_entities e ON e.id=t.id LEFT JOIN public.forge_vtt_private_data p ON p.entity_id=t.id AND p.scope='controller' WHERE t.campaign_id=c AND EXISTS(SELECT 1 FROM jsonb_array_elements(changes) ch WHERE ch->>'kind'='token' AND ch->>'id'=t.id::text);
 result:=forge_vtt_private.p4_apply_changes(c,op,changes);
 FOR item IN SELECT value FROM jsonb_array_elements(before_tokens) LOOP
 SELECT p.data,e.public_data INTO after_data,meta FROM public.forge_vtt_private_data p JOIN public.forge_vtt_entities e ON e.id=p.entity_id WHERE p.campaign_id=c AND p.entity_id=(item->>'id')::uuid AND p.scope='controller';
 damage:=greatest(0,coalesce((item->>'hp')::numeric,0)-coalesce((after_data->>'hp')::numeric,0))+greatest(0,coalesce((item->>'tempHp')::numeric,0)-coalesce((after_data#>>'{details,tempHp}')::numeric,0));healing:=greatest(0,coalesce((after_data->>'hp')::numeric,0)-coalesce((item->>'hp')::numeric,0));
 IF damage>0 OR healing>0 OR (item->'conditions') IS DISTINCT FROM (meta->'conditions') THEN
 INSERT INTO public.forge_vtt_messages(campaign_id,actor_id,token_id,scope,speaker,kind,body,payload) VALUES(c,auth.uid(),(item->>'id')::uuid,'controllers','Combat','combat',item->>'name'||CASE WHEN damage>0 THEN ' takes '||damage::text||' damage'||CASE WHEN (after_data->>'hp')::numeric=0 THEN ' and falls to 0 HP.' ELSE '.' END WHEN healing>0 THEN ' regains '||healing::text||' HP.' ELSE ': conditions updated.' END,jsonb_build_object('damage',damage,'healing',healing,'concentrationDC',CASE WHEN damage>0 AND coalesce(item->'conditions','[]')?'Concentrating' THEN greatest(10,floor(damage/2)) ELSE NULL END));
 PERFORM forge_vtt_private.play_notify(c);END IF;END LOOP;RETURN result;END$$;
REVOKE ALL ON FUNCTION forge_vtt_private.apply_changes(uuid,uuid,jsonb),forge_vtt_private.p4_apply_changes(uuid,uuid,jsonb) FROM PUBLIC,anon,authenticated;

COMMIT;

COMMIT;
